// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public { c = new RoundFactory(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        c.initialize();

        address ownerWhenCalledByDeployer = c.owner();

        vm.prank(caller);
        address ownerWhenCalledByCaller = c.owner();

        assertTrue(ownerWhenCalledByDeployer == ownerWhenCalledByCaller);
    }
}
